def migrate_legacy_proofs(apps, schema_editor):
    db_alias = schema_editor.connection.alias
    ProofType = apps.get_model("gamification", "ProofType")
    EcoProof = apps.get_model("gamification", "EcoProof")
    OcrAnalysis = apps.get_model("gamification", "OcrAnalysis")
    legacy_types = {
        "ELECTRICITY_BILL": ("ENERGY", "Facture d'électricité"),
        "TRANSPORT_TICKET": ("MOBILITY", "Ticket de transport"),
        "TEXTILE_LABEL": ("TEXTILE", "Étiquette textile"),
        "OTHER": ("ENGAGEMENT", "Autre"),
    }

    for old_code in EcoProof.objects.using(db_alias).values_list("proof_type", flat=True).distinct():
        code = old_code if old_code in legacy_types else "OTHER"
        category, label = legacy_types[code]
        proof_type, _ = ProofType.objects.using(db_alias).get_or_create(
            code=code,
            defaults={
                "category": category,
                "label_fr": label,
                "action_type": f"PROOF_{code}",
                "cap_count": 1,
                "cap_period": "MONTH",
                "photo_only": code == "TEXTILE_LABEL",
                "requires_date": code != "TEXTILE_LABEL",
            },
        )

        proofs = EcoProof.objects.using(db_alias).filter(proof_type=old_code)
        for proof in proofs.iterator():
            proof.proof_type_new_id = proof_type.pk
            proof.legacy_file_path = proof.file.name if proof.file else ""
            proof.legacy_source_url = proof.source_url or ""
            proof.file_sha256 = proof.file_hash or ""
            proof.document_date = proof.proof_date
            proof.rejection_reason_fr = proof.rejection_reason or ""
            proof.save(
                using=db_alias,
                update_fields=[
                    "proof_type_new",
                    "legacy_file_path",
                    "legacy_source_url",
                    "file_sha256",
                    "document_date",
                    "rejection_reason_fr",
                ],
            )

    for analysis in OcrAnalysis.objects.using(db_alias).select_related("eco_proof").iterator():
        proof = analysis.eco_proof
        proof.document_date = proof.document_date or analysis.extracted_date
        proof.amount = analysis.extracted_amount
        proof.merchant = analysis.extracted_merchant or ""
        proof.save(
            using=db_alias,
            update_fields=["document_date", "amount", "merchant"],
        )
        confidence = analysis.confidence_score
        analysis.mean_confidence = max(0.0, min(1.0, confidence if confidence <= 1 else confidence / 100))
        analysis.save(using=db_alias, update_fields=["mean_confidence"])


def reverse_legacy_proofs(apps, schema_editor):
    db_alias = schema_editor.connection.alias
    EcoProof = apps.get_model("gamification", "EcoProof")
    OcrAnalysis = apps.get_model("gamification", "OcrAnalysis")
    for proof in EcoProof.objects.using(db_alias).iterator():
        proof.proof_type = proof.proof_type_new.code
        proof.file = proof.legacy_file_path
        proof.source_url = proof.legacy_source_url
        proof.file_hash = proof.file_sha256
        proof.proof_date = proof.document_date
        proof.rejection_reason = proof.rejection_reason_fr
        proof.save(
            using=db_alias,
            update_fields=[
                "proof_type",
                "file",
                "source_url",
                "file_hash",
                "proof_date",
                "rejection_reason",
            ],
        )
    for analysis in OcrAnalysis.objects.using(db_alias).select_related("eco_proof").iterator():
        analysis.extracted_date = analysis.eco_proof.document_date
        analysis.extracted_amount = analysis.eco_proof.amount
        analysis.extracted_merchant = analysis.eco_proof.merchant
        analysis.confidence_score = analysis.mean_confidence
        analysis.save(
            using=db_alias,
            update_fields=[
                "extracted_date",
                "extracted_amount",
                "extracted_merchant",
                "confidence_score",
            ],
        )


